def render_block_image(self: 'HTMLRenderer', src: str, alt: Optional[str]=
    None, width: Optional[str]=None, height: Optional[str]=None, **attrs: Any
    ) ->str:
    img = '<img src="' + escape_url(src) + '"'
    if alt is not None:
        img += ' alt="' + escape_text(alt) + '"'
    if width is not None:
        img += ' width="' + width + '"'
    if height is not None:
        img += ' height="' + height + '"'
    align = attrs.get('align')
    if align:
        img += ' align="' + align + '"'
    img += ' />'
    target = attrs.get('target')
    if target:
        return '<a href="' + target + '">' + img + '</a>\n'
    return img + '\n'
